@startuml

class Doctor {
  + practitionerNumber : int
  + signature : string
  + fullName : string
  + address : string
  + phoneNumber : string
}

class Patient {
  + healthNumber : string
  + firstName : string
  + lastName : string
  + dateOfBirth : date
  + address : string
  + phoneNumber : string
}

class Requisition {
  + validFrom : date
  + repetitionCount : int
  + repetitionInterval : Interval
}

enum Interval {
  WEEKLY
  MONTHLY
  HALF_YEARLY
  YEARLY
}

class Test {
  + name : string
  + duration : int
  + isWalkIn : boolean
  + requiresSampleDropOff : boolean
}

class TestGroup {
  + groupName : string
}

class Lab {
  + address : string
  + registrationNumber : string
  + startTime : time
  + endTime : time
  + cancellationFee : float
}

class Appointment {
  + confirmationNumber : string
  + date : date
  + startTime : time
  + endTime : time
}

class TestResult {
  + isPositive : boolean
  + report : string
}

Doctor "1" -- "*" Requisition : prescribes
Patient "1" -- "*" Requisition : is subject of
Requisition "1" *-- "1..*" Test : contains
Test "*" -- "1" TestGroup : belongs to
Requisition "0..1" -- "0..1" Appointment : for repeated tests
Appointment "1" -- "1" Lab : at
Appointment "1" -- "1" Test : for
Appointment "1" -- "1" Requisition : for
Patient "1" -- "*" Appointment : books
Patient "1" -- "*" TestResult : views
Doctor "1" -- "*" TestResult : views
Test "1" -- "0..*" TestResult : has

@enduml

